const titles = {home:'工作台',routes:'学习路线',route:'路线详情',plans:'我的学习',plan:'学习计划',experiences:'前辈经验',experience:'经验详情',meetings:'组会空间',meeting:'组会详情',resources:'我的云盘',resource:'资料详情',tasks:'任务与反馈',task:'任务详情',progress:'研究记录',assistant:'科研助手',settings:'空间与权限',notifications:'通知',search:'全站搜索'};
